 public static class FrogAuthoring
 {
  public const string Folder="TruckFrogger",Scene="Assets/TruckFrogger/Scenes/TruckFrogger.unity";
  static Material asphalt,grass,steel,yellow,water,wood;static PhysicsMaterial contact;
  public static void Create()
  {
   if(File.Exists(Scene))throw new InvalidOperationException("Preserve the authored Frogger scene; targeted repairs only.");var m=SportsEventAuthoring.Begin<FrogMatch>(Folder);m.setup.count=4;m.option=0;m.NormalizeSetup();for(int i=1;i<8;i++)m.setup.players[i].source=LWS.TruckBowling.BowlingSource.AI;m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();Directory.CreateDirectory("Assets/"+Folder+"/Meshes");
   asphalt=SportsEventAuthoring.Mat(Folder,"Crossing weathered asphalt",new Color(.28f,.3f,.32f),.15f);asphalt.mainTexture=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckSnake/Materials/Open-road textured asphalt.mat").mainTexture;var baseAsphalt=asphalt;if(!LwsWeatheradeMaterialFactory.TryCreateWeatheradeRoadSurfaceMaterial("Exposed crossing road with actual snow",baseAsphalt,baseAsphalt.color,LwsWeatheradeSurfaceMaterialMode.Snow,out asphalt))throw new InvalidOperationException("Existing Weatherade road shader required");asphalt.SetFloat("_Smoothness",.18f);asphalt=SaveMaterial(asphalt,"Assets/"+Folder+"/Materials/Accumulating crossing asphalt.mat");
   grass=SportsEventAuthoring.Mat(Folder,"Riverside Vista meadow",new Color(.43f,.55f,.31f));grass.mainTexture=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer").diffuseTexture;grass.mainTextureScale=Vector2.one*24;
   steel=SportsEventAuthoring.Mat(Folder,"Worn galvanized crossing machinery",new Color(.4f,.45f,.48f),.6f);steel.SetFloat("_Metallic",.6f);yellow=SportsEventAuthoring.Mat(Folder,"Safety yellow industrial enamel",new Color(.98f,.62f,.035f),.4f);water=Object.Instantiate(AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckBogSnorkelling/Materials/Bog vendor water surface.mat"));water.name="Frogger existing animated River Modeler surface";water=SaveMaterial(water,"Assets/"+Folder+"/Materials/River Modeler crossing water.mat");wood=SportsEventAuthoring.Mat(Folder,"Railway sleepers weathered timber",new Color(.27f,.19f,.12f));contact=SportsEventAuthoring.Contact(Folder,"Truck crossing grounded contact",.75f,.02f);
   m.world=new GameObject("Five independent authored crossing challenges").AddComponent<FrogWorld>();m.world.courses=new FrogWorld.Course[5];string[] titles={"Traffic Nightmare","Rail Crossing","River Crossing","Industrial Chaos","Ultimate Crossing"};
   for(int course=0;course<5;course++)
   {
    float x=course*620;var root=new GameObject(titles[course]+" complete independent challenge").transform;root.position=Vector3.right*x;var actors=new GameObject("Recorded UTS traffic and physical crossing machinery").transform;actors.SetParent(root,false);var c=new FrogWorld.Course{title=titles[course],root=root,actors=actors,start=new Vector3(x,.65f,-30),finish=new Vector3(x,0,course==4?490:320),halfWidth=24};m.world.courses[course]=c;
    c.water=course==2?new[]{new Vector2(65,110),new Vector2(170,215)}:course==4?new[]{new Vector2(230,275)}:Array.Empty<Vector2>();
    var strips=new List<Vector2>();float from=-90;foreach(var gap in c.water){strips.Add(new Vector2(from,gap.x));from=gap.y;}strips.Add(new Vector2(from,c.finish.z+70));
    foreach(var strip in strips){var ground=SportsEventAuthoring.Box("Continuous dressed riverbank driving terrain",new Vector3(x,-.7f,(strip.x+strip.y)*.5f),new Vector3(580,1,strip.y-strip.x),grass,contact,root);ground.transform.position=new Vector3(x,-.7f,(strip.x+strip.y)*.5f);SportsDrivingSurfaceAuthoring.MarkHierarchy(ground.transform);Road(root,new[]{new Vector3(x,0,strip.x),new Vector3(x,0,strip.y)},32,"Player crossing road "+course+" "+strip.x);}
    foreach(var gap in c.water){var surface=GameObject.CreatePrimitive(PrimitiveType.Plane);surface.name="Existing animated River Modeler crossing water";surface.transform.SetParent(root,false);surface.transform.localPosition=new Vector3(0,-2.5f,(gap.x+gap.y)*.5f);surface.transform.localScale=new Vector3(58,1,(gap.y-gap.x)/10);Object.DestroyImmediate(surface.GetComponent<Collider>());surface.GetComponent<Renderer>().sharedMaterial=water;SportsEventAuthoring.Box("Submerged riverbed",new Vector3(0,-13,(gap.x+gap.y)*.5f),new Vector3(390,1,gap.y-gap.x),grass,contact,root);for(int bank=0;bank<2;bank++)for(int j=0;j<15;j++)SportsEventAuthoring.Box("Timber quay retaining face",new Vector3(-175+j*25,-2,bank==0?gap.x:gap.y),new Vector3(24,3,.6f),wood,contact,root);}
    var movers=new List<FrogMover>();var gates=new List<Vector3>();
    if(course==0||course==4){float[] roads=course==0?new[]{45f,105,165,225}:new[]{45f,105};c.traffic=Traffic(root,actors,x,roads,course);foreach(float z in roads)gates.Add(new Vector3(x,0,z));}
    if(course==1||course==4){float[] tracks=course==1?new[]{55f,120,185,250}:new[]{175f};foreach(float z in tracks){Rails(root,x,z);movers.Add(Train(actors,x,z,movers.Count));gates.Add(new Vector3(x,0,z));}}
    if(course==2||course==4)foreach(var gap in c.water){float z=(gap.x+gap.y)*.5f;movers.Add(Barge(actors,x,z,gap.y-gap.x+8,movers.Count));gates.Add(new Vector3(x,0,z));}
    if(course==3||course==4){float[] zones=course==3?new[]{50f,115,180,245}:new[]{335f,410};foreach(float z in zones){movers.Add(Loader(actors,x,z,movers.Count));movers.Add(Forklift(actors,x,z+8,movers.Count));gates.Add(new Vector3(x,0,z));for(int side=-1;side<=1;side+=2)Model(root,"Assets/ShipContainerPack/URP/Prefabs/ShipContainerRed_URP.prefab",new Vector3(x+side*48,0,z+20),new Vector3(12,7,8));}}
    c.movers=movers.ToArray();c.gates=gates.OrderBy(p=>p.z).ToArray();Dress(root,c,course);Finish(root,c);c.root.gameObject.SetActive(course==0);
   }
   m.trucks=new SportsEventTruck[8];m.fragments=new SportsFragmentRig[8];for(int i=0;i<8;i++){var t=FareFightVehicleAuthoring.Spawn(m,i,new Vector3(i*13,.65f,-65),Quaternion.identity);m.trucks[i]=t;m.fragments[i]=SportsFragmentAuthoring.InstallRigid(t.body,t.visuals.GetComponentsInChildren<MeshFilter>(true),Folder);var contacts=t.gameObject.AddComponent<FrogContacts>();contacts.match=m;contacts.truck=t;}
   m.broadcast=SportsEventAuthoring.Camera("Active crossing driver broadcast");m.broadcast.view.farClipPlane=2200;m.framing=m.broadcast.gameObject.AddComponent<SportsCameraFit>();m.framing.cameraTarget=m.broadcast.view;m.cameras=new[]{m.broadcast.view};SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);m.drivingViews=SportsDrivingViewsAuthoring.Install(m,m.trucks,m.broadcast,Folder);m.drivingViews.independentViewModes=true;m.drivingViews.localElevated=true;m.drivingViews.defaultMode=1;foreach(var v in m.drivingViews.rally.views)v.view.farClipPlane=2200;
   m.atmosphere=SportsChaosAuthoring.Weather(m,Folder);m.atmosphere.presets=SportsWeatherPresetsAuthoring.EnsureCatalog();m.drivingViews.rally.weather=m.atmosphere;SportsWeatherPickerAuthoring.Install(m,m.atmosphere.presets,new Vector2(350,-180));SportsUIAuthoring.Button(m.menus.pages[6].transform,"WATCH CROSSING HIGHLIGHTS","watchfrog",new Vector2(0,-245),new Vector2(520,48));Artwork(m);SportsBroadcastAuthoring.ApplyScene();SportsScenicGradeAuthoring.Install(m.gameObject,new[]{m.broadcast.view}.Concat(m.drivingViews.rally.views.Select(v=>v.view)).ToArray(),Folder,-.15f);SportsMatchAudioAuthoring.Install(m,m.trucks);SportsEventAuthoring.Save(Folder);m.GetComponent<SportsSnowSurface>().traceExposedRoads=true;UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();
  }
  static Material SaveMaterial(Material value,string path){var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing==null){AssetDatabase.CreateAsset(value,path);return value;}EditorUtility.CopySerialized(value,existing);Object.DestroyImmediate(value);EditorUtility.SetDirty(existing);return existing;}
  static void Road(Transform root,Vector3[] points,float width,string title){LWS.TruckTaxi.Editor.TruckTaxiDemoBuilder.BakeRegionalRoads(root,new List<Vector3[]>{points},width,title,asphalt,"Assets/"+Folder+"/Meshes");}
  static FrogTraffic Traffic(Transform root,Transform actors,float x,float[] rows,int course)
  {
   var traffic=new GameObject("Public LWS to UTS crossing-traffic adapter").AddComponent<FrogTraffic>();traffic.transform.SetParent(root,false);traffic.fleet=actors;traffic.prefabs=new[]{AssetDatabase.LoadAssetAtPath<GameObject>("Assets/UTS_FullPack/Models/Cars/Car_Prefabs/Day Cars/Car_1.prefab"),AssetDatabase.LoadAssetAtPath<GameObject>("Assets/UTS_FullPack/Models/Cars/Car_Prefabs/Day Cars/Car_2.prefab")};var lanes=new List<LwsTrafficLaneDefinition>();
   for(int i=0;i<rows.Length;i++){float z=rows[i];var points=new List<Vector3>();for(int side=0;side<4;side++)for(int k=0;k<16;k++){float t=k/16f;points.Add(new Vector3(x+(side==0?Mathf.Lerp(-160,160,t):side==1?160:side==2?Mathf.Lerp(160,-160,t):-160),.8f,z+(side==0?0:side==1?Mathf.Lerp(0,28,t):side==2?28:Mathf.Lerp(28,0,t))));}var road=points.Select(p=>new Vector3(p.x,0,p.z)).ToArray();Road(root,road.Concat(new[]{road[0]}).ToArray(),9,"Independent busy highway "+course+" lane "+i);lanes.Add(new LwsTrafficLaneDefinition{laneId="frog."+course+"."+i,roadId="frog.highway."+i,segmentId="frog.lane."+i,edgeId="frog.crossing."+i,laneIndex=0,laneWidthMeters=9,lengthMeters=696,speedLimitMph=25+i*4,centerline=points.ToArray()});}
   traffic.lanes=lanes.ToArray();return traffic;
  }
  static FrogMover Actor(Transform actors,string title,Vector3 p,float halfWidth,float period,bool platform,bool loop)
  {
   var root=new GameObject(title);root.transform.SetParent(actors);root.transform.position=p;var body=root.AddComponent<Rigidbody>();body.isKinematic=true;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;var mover=root.AddComponent<FrogMover>();mover.body=body;mover.origin=p;mover.halfWidth=halfWidth;mover.period=period;mover.platform=platform;mover.loop=loop;mover.phase=actors.childCount*.217f;return mover;
  }
  static FrogMover Train(Transform actors,float x,float z,int index)
  {
   var t=Actor(actors,"Physical articulated container freight train",new Vector3(x,0,z),56,19+index*2,false,true);t.travel=230;var red=SportsEventAuthoring.Mat(Folder,"Freight train oxblood enamel",new Color(.43f,.075f,.045f),.4f);
   for(int car=0;car<4;car++){float offset=(car-1.5f)*24;var chassis=SportsEventAuthoring.Box("Freight bogie supporting chassis",new Vector3(offset,1.2f,0),new Vector3(22,1,6),steel,contact,t.transform);Model(t.transform,"Assets/ShipContainerPack/URP/Prefabs/ShipContainerRed_URP.prefab",new Vector3(offset,1.7f,0),new Vector3(21,7,5.5f),true);for(int a=-1;a<=1;a+=2)for(int side=-1;side<=1;side+=2){var wheel=GameObject.CreatePrimitive(PrimitiveType.Cylinder);wheel.name="Freight train visible steel rail wheel";wheel.transform.SetParent(t.transform,false);wheel.transform.localPosition=new Vector3(offset+a*7,.85f,side*2.65f);wheel.transform.localRotation=Quaternion.Euler(90,0,0);wheel.transform.localScale=new Vector3(1.8f,.35f,1.8f);Object.DestroyImmediate(wheel.GetComponent<Collider>());wheel.GetComponent<Renderer>().sharedMaterial=steel;}}
   SportsEventAuthoring.Box("Freight engine sloped cabin",new Vector3(-52,3,0),new Vector3(8,5,5.7f),red,contact,t.transform);SportsEventAuthoring.Box("Freight engine front windshield",new Vector3(-56.1f,4,0),new Vector3(.08f,2,4.3f),asphalt,null,t.transform);return t;
  }
  static FrogMover Barge(Transform actors,float x,float z,float length,int index)
  {
   var t=Actor(actors,"Actual moving cargo barge bridge",new Vector3(x,-.1f,z),10.5f,24+index*4,true,false);t.travel=21;var deck=SportsEventAuthoring.Box("Traversable barge steel deck",new Vector3(0,-.45f,0),new Vector3(21,.7f,length),steel,contact,t.transform);SportsDrivingSurfaceAuthoring.MarkHierarchy(deck.transform);var hull=new GameObject("Existing original expedition boat hull");hull.transform.SetParent(t.transform,false);hull.transform.localPosition=Vector3.down*2;hull.transform.localScale=new Vector3(5.25f,1.4f,length/9f);hull.AddComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/TruckSkyTow/Art/Original expedition boat hull.asset");hull.AddComponent<MeshRenderer>().sharedMaterial=water;foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Readable barge side safety rail",new Vector3(side*10.5f,.7f,0),new Vector3(.3f,1.5f,length),yellow,contact,t.transform);return t;
  }
  static FrogMover Loader(Transform actors,float x,float z,int index)
  {
   var t=Actor(actors,"Physical industrial straddle-loader and forklift crossing",new Vector3(x,0,z),10,26+index*2,false,false);t.travel=105;
   foreach(int side in new[]{-1,1}){SportsEventAuthoring.Box("Container loader vertical structural leg",new Vector3(side*7,6,0),new Vector3(1.2f,12,4),yellow,contact,t.transform);for(int end=-1;end<=1;end+=2){var tire=GameObject.CreatePrimitive(PrimitiveType.Cylinder);tire.name="Straddle carrier functional collision tire";tire.transform.SetParent(t.transform,false);tire.transform.localPosition=new Vector3(side*7,1.6f,end*3);tire.transform.localRotation=Quaternion.Euler(0,0,90);tire.transform.localScale=new Vector3(3.2f,.9f,3.2f);tire.GetComponent<Renderer>().sharedMaterial=asphalt;}}
   SportsEventAuthoring.Box("Container handler overhead structural beam",new Vector3(0,12,0),new Vector3(16,1.2f,4),yellow,contact,t.transform);Model(t.transform,"Assets/ShipContainerPack/URP/Prefabs/ShipContainerRed_URP.prefab",new Vector3(0,4,0),new Vector3(12,6,6),true);foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Visible container suspension hoist",new Vector3(side*4,10,0),new Vector3(.12f,4,.12f),steel,null,t.transform);return t;
  }
  static FrogMover Forklift(Transform actors,float x,float z,int index)
  {
   var t=Actor(actors,"Actual crossing forklift with raised mast and forks",new Vector3(x,0,z),4.5f,28+index*2,false,false);t.travel=80;t.phase+=.4f;
   SportsEventAuthoring.Box("Counterweight forklift curved-base chassis",new Vector3(0,1,0),new Vector3(6,1.8f,3.8f),yellow,contact,t.transform);SportsEventAuthoring.Box("Forklift operator seat",new Vector3(0,2.25f,0),new Vector3(1.4f,.55f,1.6f),asphalt,null,t.transform);
   foreach(int side in new[]{-1,1}){SportsEventAuthoring.Box("Forklift overhead cage upright",new Vector3(side*1.4f,3,1.65f),new Vector3(.2f,3.4f,.2f),steel,null,t.transform);SportsEventAuthoring.Box("Functional raised forklift mast",new Vector3(-3.2f,3,side*1.2f),new Vector3(.4f,6,.3f),steel,contact,t.transform);SportsEventAuthoring.Box("Readably protruding physical forklift fork",new Vector3(-4.7f,.6f,side*1.2f),new Vector3(3.5f,.25f,.45f),steel,contact,t.transform);for(int axle=-1;axle<=1;axle+=2){var wheel=GameObject.CreatePrimitive(PrimitiveType.Cylinder);wheel.name="Forklift rubber tire";wheel.transform.SetParent(t.transform,false);wheel.transform.localPosition=new Vector3(axle*2,.8f,side*1.9f);wheel.transform.localRotation=Quaternion.Euler(90,0,0);wheel.transform.localScale=new Vector3(1.6f,.4f,1.6f);wheel.GetComponent<Renderer>().sharedMaterial=asphalt;}}
   SportsEventAuthoring.Box("Forklift operator safety roof",new Vector3(0,4.8f,0),new Vector3(4.5f,.25f,3.9f),yellow,null,t.transform);return t;
  }
  static void Rails(Transform root,float x,float z){foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Actual steel freight rail",new Vector3(0,.05f,z+side*2.7f),new Vector3(385,.13f,.16f),steel,null,root);for(int j=0;j<77;j++)SportsEventAuthoring.Box("Grounded timber railway sleeper",new Vector3(-190+j*5,-.08f,z),new Vector3(.7f,.16f,6.3f),wood,null,root);}
  static void Dress(Transform root,FrogWorld.Course c,int index)
  {
   for(int side=-1;side<=1;side+=2)for(int j=0;j<8;j++){var p=new Vector3(c.start.x+side*(205+j%2*35),0,-25+j*48);string path=index==0?"Assets/JC_LP_MegaCity/Prefabs/Buildings/SM_Buildings_Warehouse_01.prefab":"Assets/TruckSnake/Prefabs/Original Vista pine.prefab";Model(root,path,p,index==0?new Vector3(50,30,35):new Vector3(14,28,14));}
   foreach(var gate in c.gates){var sign=SportsEventAuthoring.Label("Readable crossing warning","WAIT FOR A GAP",new Vector3(gate.x+21,7,gate.z-25),.12f,new Color(1,.82f,.15f));sign.transform.SetParent(root,true);SportsEventAuthoring.Box("Warning sign steel post",new Vector3(21,3.5f,gate.z-25),new Vector3(.25f,7,.25f),steel,contact,root);}
   // Source purchased scenery is reused unchanged; mode-owned road/rail and
   // straddle-loader geometry supplies the genuinely missing obstacle shapes.
  }
  static void Finish(Transform root,FrogWorld.Course c){for(int x=-4;x<=4;x++)for(int z=0;z<2;z++)SportsEventAuthoring.Box("Flush checkered full-truck finish marking",new Vector3(x*5,.08f,c.finish.z+z*3),new Vector3(5,.02f,3),(x+z)%2==0?yellow:asphalt,null,root);foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Grounded finish gantry leg",new Vector3(side*25,7,c.finish.z),new Vector3(.7f,14,.7f),steel,contact,root);SportsEventAuthoring.Box("Finish gantry crossbeam",new Vector3(0,14,c.finish.z),new Vector3(51,.8f,.8f),steel,null,root);var label=SportsEventAuthoring.Label("Unmistakable crossing finish","CROSSING CLEAR",c.finish+Vector3.up*12,.12f,Color.white);label.transform.SetParent(root,true);}
  static void Model(Transform parent,string path,Vector3 world,Vector3 size,bool local=false){var holder=new GameObject("Owned instance · "+Path.GetFileNameWithoutExtension(path)).transform;holder.SetParent(parent,true);if(local)holder.localPosition=world;else holder.position=world;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,path,size,0,true,Folder);foreach(var filter in holder.GetComponentsInChildren<MeshFilter>())if(filter.sharedMesh!=null){var collider=filter.gameObject.AddComponent<MeshCollider>();collider.sharedMesh=filter.sharedMesh;if(holder.GetComponentInParent<Rigidbody>()!=null)collider.convex=true;}}
  static void Artwork(FrogMatch m){var logo=SportsRetroMenuAuthoring.LoadLogo(Folder);foreach(int i in new[]{0,4}){var page=m.menus.pages[i];var art=SportsUIAuthoring.Rect("Original sport title artwork",page.transform,new Vector2(260,160),new Vector2(-560,365)).AddComponent<UnityEngine.UI.Image>();art.sprite=logo;art.preserveAspect=true;art.raycastTarget=false;var title=page.transform.Find("Title").GetComponent<TMP_Text>();title.rectTransform.anchoredPosition+=Vector2.right*140;title.rectTransform.sizeDelta=new Vector2(1000,title.rectTransform.sizeDelta.y);}var material=SportsEventAuthoring.Mat(Folder,"Original grungy crossing venue logo",Color.white);material.shader=Shader.Find("Universal Render Pipeline/Unlit");material.mainTexture=logo.texture;material.SetFloat("_Surface",1);material.SetFloat("_SrcBlend",5);material.SetFloat("_DstBlend",10);material.SetFloat("_ZWrite",0);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.renderQueue=3000;foreach(var c in m.world.courses){var sign=GameObject.CreatePrimitive(PrimitiveType.Quad);sign.name="Original Frogger finish gantry artwork";Object.DestroyImmediate(sign.GetComponent<Collider>());sign.transform.SetParent(c.root,true);sign.transform.position=c.finish+new Vector3(0,23,1);sign.transform.localScale=new Vector3(25,16,1);sign.GetComponent<Renderer>().sharedMaterial=material;foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Grounded branded finish structure",new Vector3(side*13,15,c.finish.z+1),new Vector3(.5f,30,.5f),steel,contact,c.root);}}
 }
